const __aivicBundle_6_calculateNutrientAchievementRate = (() => {
  function calculateNutrientAchievementRate(input: {
    targetValue: number;
    actualValue: number;
  }): number {
    const { targetValue, actualValue } = input;
  
    if (targetValue === 0) {
      throw new Error('Target value cannot be zero');
    }
  
    if (actualValue === 0) {
      return 0;
    }
  
    const achievementRate = (actualValue / targetValue) * 100;
    return achievementRate;
  }
  return { calculateNutrientAchievementRate };
})();
