const __aivicBundle_16_anonymizeExpiredMealEvaluationData = (() => {
  function anonymizeExpiredMealEvaluationData(params: {
    evaluationData: Array<{
      id: string;
      userId: string;
      userName: string;
      mealId: string;
      satisfactionScore: number;
      completionRate: number;
      requestComment: string;
      registeredAt: Date;
    }>;
    policy: {
      retentionDays: number;
      anonymizeExpiredData: boolean;
    };
    currentDate: Date;
  }): {
    anonymized: Array<{
      id: string;
      userId: null;
      userName: null;
      satisfactionScore: number;
      completionRate: number;
      requestComment: string;
      registeredAt: Date;
    }>;
    retained: Array<{
      id: string;
      userId: string;
      userName: string;
      satisfactionScore: number;
      completionRate: number;
      requestComment: string;
      registeredAt: Date;
    }>;
  } {
    const { evaluationData, policy, currentDate } = params;
    const { retentionDays, anonymizeExpiredData } = policy;
  
    const anonymized: Array<{
      id: string;
      userId: null;
      userName: null;
      satisfactionScore: number;
      completionRate: number;
      requestComment: string;
      registeredAt: Date;
    }> = [];
  
    const retained: Array<{
      id: string;
      userId: string;
      userName: string;
      satisfactionScore: number;
      completionRate: number;
      requestComment: string;
      registeredAt: Date;
    }> = [];
  
    for (const record of evaluationData) {
      const expirationDate = new Date(record.registeredAt);
      expirationDate.setDate(expirationDate.getDate() + retentionDays);
  
      const isExpired = expirationDate < currentDate;
  
      if (isExpired && anonymizeExpiredData) {
        anonymized.push({
          id: record.id,
          userId: null,
          userName: null,
          satisfactionScore: record.satisfactionScore,
          completionRate: record.completionRate,
          requestComment: record.requestComment,
          registeredAt: record.registeredAt,
        });
      } else if (!isExpired) {
        retained.push({
          id: record.id,
          userId: record.userId,
          userName: record.userName,
          satisfactionScore: record.satisfactionScore,
          completionRate: record.completionRate,
          requestComment: record.requestComment,
          registeredAt: record.registeredAt,
        });
      }
    }
  
    return {
      anonymized,
      retained,
    };
  }
  return { anonymizeExpiredMealEvaluationData };
})();
